extern "C" void auction(const double* c, int n, int* ans) {
 std::vector<double> p(n,0.0); std::vector<int> own(n), q(n);
 double eps=.05;
 while(eps>1e-11) {
   std::fill(own.begin(),own.end(),-1); std::fill(ans,ans+n,-1);
   int head=0,tail=n; for(int i=0;i<n;i++)q[i]=i;
   // queue can require arbitrary expansion
   std::vector<int> que; que.reserve(n*20); for(int i=0;i<n;i++)que.push_back(i);
   size_t h=0;
   while(h<que.size()) {
    int i=que[h++]; const double* row=c+(size_t)i*n;
    int bj=-1; double best=-1e300, second=-1e300;
    for(int j=0;j<n;j++) { double v=-row[j]-p[j]; if(v>best){second=best;best=v;bj=j;} else if(v>second)second=v; }
    p[bj] += best-second+eps;
    int old=own[bj]; own[bj]=i; ans[i]=bj;
    if(old>=0){ans[old]=-1;que.push_back(old);}
   }
   eps *= .1;
 }
}
