#include <vector>
#include <algorithm>
#include <cmath>
extern "C" void hung(const double* a,int n,int* ans){
 std::vector<double> u(n+1),v(n+1),minv(n+1); std::vector<int> p(n+1),way(n+1); std::vector<unsigned char> used(n+1);
 for(int i=1;i<=n;i++){
  p[0]=i; int j0=0; std::fill(minv.begin()+1,minv.end(),1e100); std::fill(used.begin(),used.end(),0);
  do { used[j0]=1; int i0=p[j0],j1=0; double delta=1e100; const double* row=a+(size_t)(i0-1)*n;
   for(int j=1;j<=n;j++) if(!used[j]) {double cur=row[j-1]-u[i0]-v[j]; if(cur<minv[j])minv[j]=cur,way[j]=j0; if(minv[j]<delta)delta=minv[j],j1=j;}
   for(int j=0;j<=n;j++)if(used[j])u[p[j]]+=delta,v[j]-=delta;else minv[j]-=delta;
   j0=j1;
  }while(p[j0]);
  do {int j1=way[j0];p[j0]=p[j1];j0=j1;}while(j0);
 }
 for(int j=1;j<=n;j++)ans[p[j]-1]=j-1;
}
